'use strict';
const wb={spec:null,imageData:null,activeGroup:'CPU信息',dynamic:{},monthly:{},dateStart:'',dateEnd:'',timeStart:'',timeEnd:'',operators:{cpu:'>',memory:'>',disk:'>'},coverage:{}};
const WB_LABELS={architecture:'架构',ipv4_connectivity_type:'IPv4 接入类型',native_ip_status:'原生 IP 状态',usage_location:'使用地（口径待明确）',registration_location:'注册地（口径待明确）',memory_overcommit_indicators:'内存机制迹象'};
const WB_REASONS={usage_location:'尚无清晰定义且可关联到具体对象的 IP 使用地。',registration_location:'未把 IP 注册地、商家注册地或机房位置互相替代。',datacenter:'产品城市不等于确认的机房名称。',architecture:'现有结构化资料未明确报告架构。',sysbench_cpu_single:'已有历史读数，但版本、单位或参数不全，暂不跨记录筛选。',sysbench_cpu_multi:'版本与线程参数不全；历史读数可在详情查看。',sysbench_memory_read:'历史读数的测试版本和参数不完整。',sysbench_memory_write:'历史读数的测试版本和参数不完整。',hardware_total_score:'缺少一致的评分工具与版本，不拼造统一总分。',hardware_cpu_score:'未取得可按同一评分工具与版本筛选的记录。',hardware_gpu_score:'未报告的 GPU 分数保留未知，不记为 0。',hardware_memory_score:'缺少一致评分口径。',hardware_disk_score:'不把 MB/s 直接当作硬盘总得分。',ipv4_connectivity_type:'暂未有独立 IP / NAT 等精确结构化证据。',native_ip_status:'解锁结果不等于原生 IP；有争议的来源判断只保留在详情。',ipv4_ping:'已读网络图主要是 TCPQuality 延迟或测速 RTT，不能当作统一平均 Ping。',ipv6_ping:'IPv6 单列；不以 IPv4 或选取样本代替平均 Ping。',nat_type:'没有可靠的 NAT 类型测试记录。',outbound_routes:'当前已核结构化线路主要是服务器到国内的回程。'};
const WB_MULTIS=new Set(['usage_location','registration_location','datacenter','asn','organization','traffic_billing','virtualization','architecture','operating_system','cpu_vendor','memory_overcommit_indicators','ipv4_connectivity_type','ipv6_availability','native_ip_status','nat_type']);
function fieldLabel(key){return WB_LABELS[key]||wb.spec?.fields.find(f=>f.key===key)?.label||key;}
function activeImageFacts(item,key,onlyEligible=true){if(pipelineRecordStatus(item.skillReview)==='accepted')return [];return (item.imageEvidence?.fieldObservations||[]).filter(f=>f.fieldKey===key&&(!onlyEligible||(f.filterEligible&&f.isPrimary))&&f.value!=null);}
function fieldValues(item,key){if(key==='city'&&item.skillReview){const city=getFilterCity(item);return city?[city]:[];}if(item.skillReview&&['vcpu','memory_capacity','disk_capacity'].includes(key)){const sf=skillFact(item,{vcpu:'vcpu',memory_capacity:'memory_gb',disk_capacity:'disk_gb'}[key]);if(sf&&!sf.filterEligible)return [];}const c=item.configuration||{},q=item.trafficQuota||{};let values=[];
 const scalar={vcpu:c.vcpu,memory_capacity:capacity(c.memoryValue,c.memoryUnit),disk_capacity:capacity(c.diskValue,c.diskUnit),country_region:item.location?.country,city:getFilterCity(item),provider:item.vendor,cpu_model:c.cpuModel,disk_type:getDiskType(item),cpu_vendor:/^AMD\b/i.test(c.cpuModel||'')?'AMD':/^Intel\b/i.test(c.cpuModel||'')?'Intel':null}[key];if(scalar!=null&&scalar!=='')values.push(scalar);
 if(key==='traffic_billing'&&q.direction)values.push(q.direction);
 if(key==='monthly_traffic'&&['monthly','month','月','每月'].includes(q.period)&&isKnownNumber(q.value)){if(q.unit==='TB')values.push(q.value);else if(q.unit==='GB')values.push(q.value/1000);}
 if(key==='port_bandwidth')for(const b of item.bandwidthClaims||[]){if(isKnownNumber(b.advertisedPortMbps))values.push(b.advertisedPortMbps/1000);else if(isKnownNumber(b.advertisedMbps))values.push(b.advertisedMbps/1000);}
 for(const f of activeImageFacts(item,key)){if(Array.isArray(f.value))values.push(...f.value);else values.push(f.value);}
 if(key==='asn')values=values.map(v=>String(v).trim()).filter(v=>/^AS\d+$/i.test(v));
 values.push(...skillFieldValues(item,key));return [...new Set(values.filter(v=>v!=null&&v!==''))];
}
function knownTimes(item){if(item.skillReview)return skillReportTimes(item);const reports=[...(item.testedAt?.reports||[]),...(item.imageEvidence?.imageReportTimes||[]).map(r=>r.testTime)];return [...new Set(reports.filter(r=>r?.beijing&&/\+08:00$/.test(r.beijing)).map(r=>r.beijing))];}
function monthlyValue(p){if(p.monthlyQuote!=null&&isKnownNumber(p.monthlyQuote)&&p.currency&&p.filterEligible!==false)return p.monthlyQuote;if(p.filterEligible===false||!isKnownNumber(p.amount)||!p.currency)return null;const months={monthly:1,quarterly:3,yearly:12,two_years:24,three_years:36}[p.billingPeriod];return months?p.amount/months:null;}
function monthlyRecords(item){if(item.skillReview)return skillMonthlyRecords(item);return priceRecords(item).filter(p=>monthlyValue(p)!=null).map(p=>({...p,monthly:monthlyValue(p)}));}
function canonicalRoute(s){return String(s).replace(/CN2GIA/gi,'CN2 GIA').replace(/CN2GT/gi,'CN2 GT').replace(/CTGGIA/gi,'CTG GIA').trim();}
function exactRoutes(item){if(item.skillReview)return skillRouteRows(item);const out=[];for(const r of (item.imageEvidence?.routeObservations?.length?[]:item.network?.routeObservations||[])){const direction=r.direction==='回程'?'return':r.direction==='去程'?'outbound':null;if(!direction||!['IPv4','IPv6'].includes(r.family)||!r.operator||r.evidenceType==='author_claim')continue;for(const op of r.operator.split('/'))if(['电信','联通','移动'].includes(op))out.push({family:r.family,direction,operator:op,labels:[r.label,...(r.otherLabels||[])].filter(Boolean).map(canonicalRoute),basis:r.basis});}for(const r of item.imageEvidence?.routeObservations||[]){if(!r.filterEligible||r.isPrimary===false||!['IPv4','IPv6'].includes(r.family))continue;out.push({family:r.family,direction:r.direction,operator:r.operator||r.carrier,labels:(r.reportedLabels||[]).map(canonicalRoute),basis:'既有图片核读记录'});}return out;}
function routeCoverage(direction){return state.items.filter(i=>exactRoutes(i).some(r=>r.direction===direction)).length;}
function coverageFor(key){if(key==='test_date'||key==='test_time_bjt')return state.items.filter(i=>knownTimes(i).length).length;if(key==='monthly_price')return state.items.filter(i=>monthlyRecords(i).length).length;if(key==='billing_period')return state.items.filter(i=>priceRecords(i).some(p=>p.billingPeriod)).length;if(key.startsWith('geekbench_')){const metric=key.endsWith('single')?'single':'multi';return state.items.filter(i=>benchmarks(i).some(b=>b.tool==='Geekbench'&&b.metric===metric&&b.isPrimary!==false&&benchmarkKey(b))).length;}if(key==='return_routes'||key==='outbound_routes')return routeCoverage(key==='return_routes'?'return':'outbound');return state.items.filter(i=>fieldValues(i,key).length).length;}
function thresholdPass(value,threshold,op='>'){if(threshold===''||threshold==null)return true;const n=Number(threshold);return isKnownNumber(value)&&Number.isFinite(n)&&n>=0&&(op==='>='?value>=n:value>n);}
function workbenchFiltersActive(){return Object.values(wb.dynamic).some(v=>Array.isArray(v)?v.length:v!=='')||Object.values(wb.monthly).some(v=>v.enabled)||wb.dateStart||wb.dateEnd||wb.timeStart||wb.timeEnd;}
function matchWorkbench(item,f){
 if(wb.dateStart||wb.dateEnd||wb.timeStart||wb.timeEnd){const times=knownTimes(item);if(!times.some(t=>{const d=t.slice(0,10),h=t.slice(11,16);if(wb.dateStart&&d<wb.dateStart||wb.dateEnd&&d>wb.dateEnd)return false;if(wb.timeStart&&wb.timeEnd&&wb.timeStart>wb.timeEnd)return h>=wb.timeStart||h<=wb.timeEnd;return (!wb.timeStart||h>=wb.timeStart)&&(!wb.timeEnd||h<=wb.timeEnd);}))return false;}
 for(const [key,v]of Object.entries(wb.dynamic)){if(Array.isArray(v)?!v.length:v==='')continue;if(key.startsWith('route:')){const [,direction,family,operator]=key.split(':');if(!exactRoutes(item).some(r=>r.direction===direction&&r.family===family&&r.operator===operator&&v.some(label=>r.labels.includes(label))))return false;}else{const values=fieldValues(item,key);if(Array.isArray(v)){if(!v.some(want=>want==='unknown'?!values.length:values.map(String).includes(want)))return false;}else if(!values.some(value=>isKnownNumber(value)&&value>Number(v)))return false;}}
 const ranges=Object.entries(wb.monthly).filter(([,r])=>r.enabled);if(ranges.length&&!monthlyRecords(item).some(p=>multiMatch(p.currency,f.currency)&&multiMatch(p.priceKind,f.priceKind)&&ranges.some(([currency,r])=>p.currency===currency&&p.monthly>=r.min-1e-9&&p.monthly<=r.max+1e-9)))return false;
 return true;
}
function controlCard(title,body,coverage,key,extra=''){return `<section class="field-card ${extra}" data-spec-field="${escapeHTML(key)}"><div class="field-top"><h3>${escapeHTML(title)}</h3><span>${coverage} 条有数据</span></div>${body}</section>`;}
function wbOptions(key){return [...new Set(state.items.flatMap(i=>fieldValues(i,key)).map(String))].sort((a,b)=>a.localeCompare(b,'zh-CN'));}
function wbMulti(key){const values=wbOptions(key);return `<details class="wb-multi"><summary>不限 <span>可多选</span></summary><div class="wb-options">${values.length>7?`<input type="search" data-wb-search="${key}" placeholder="搜索选项" aria-label="搜索${escapeHTML(fieldLabel(key))}">`:''}<div>${values.map(v=>`<label data-wb-option="${escapeHTML(v.toLowerCase())}"><input type="checkbox" data-wb-multi="${key}" value="${escapeHTML(v)}"><span>${escapeHTML(v)}</span></label>`).join('')}<label data-wb-option="未知"><input type="checkbox" data-wb-multi="${key}" value="unknown"><span>未知 / 未注明</span></label></div></div></details>`;}
function legacySlot(id,title,coverage,key){return controlCard(title,`<div id="${id}" class="multi-slot"></div>`,coverage,key);}
function pendingFields(fields){if(!fields.length)return '';return `<details class="pending-fields"><summary>${fields.length} 项待补可筛数据</summary><div class="pending-grid">${fields.map(f=>`<div data-spec-field="${f.key}"><strong>${escapeHTML(fieldLabel(f.key))}</strong><p>${escapeHTML(WB_REASONS[f.key]||'已有资料尚不足以建立明确单位与口径的筛选条件。')}</p></div>`).join('')}</div></details>`;}
function routeMatrix(direction){const heading=direction==='return'?'三网回程':'三网去程';const blocks=['IPv4','IPv6'].map(family=>`<section class="route-family"><h4>${family}</h4>${['电信','联通','移动'].map(operator=>{const key=`route:${direction}:${family}:${operator}`;const labels=[...new Set(state.items.flatMap(i=>exactRoutes(i).filter(r=>r.direction===direction&&r.family===family&&r.operator===operator).flatMap(r=>r.labels)))].sort();return `<div class="route-filter-row"><strong>${operator}</strong>${labels.length?`<details class="wb-multi"><summary>不限 <span>可多选</span></summary><div class="wb-options">${labels.map(v=>`<label><input type="checkbox" data-wb-multi="${key}" value="${escapeHTML(v)}"><span>${escapeHTML(v)}</span></label>`).join('')}</div></details>`:'<span class="pending-inline">暂无匹配方向的记录</span>'}</div>`;}).join('')}</section>`).join('');return controlCard(heading,`<p class="field-help">${direction==='return'?'服务器 → 中国大陆；':'中国大陆 → 服务器；'}每格精确区分协议和运营商。命中部分报告目标，不保证所有地区路线。</p><div class="route-filter-matrix">${blocks}</div>`,routeCoverage(direction),direction==='return'?'return_routes':'outbound_routes','wide-field');}
function monthlyControls(){const currencies=[...new Set(state.items.flatMap(i=>monthlyRecords(i).map(p=>p.currency)))].sort();return currencies.map(currency=>{const values=state.items.flatMap(i=>monthlyRecords(i).filter(p=>p.currency===currency).map(p=>p.monthly));const lo=Math.floor(Math.min(...values)*100)/100,hi=Math.ceil(Math.max(...values)*100)/100;wb.monthly[currency]={enabled:false,min:lo,max:hi,domainMin:lo,domainMax:hi};return `<section class="monthly-box"><label class="monthly-enable"><input type="checkbox" data-month-enable="${currency}"><strong>${currency} / 月</strong><span>${new Set(state.items.filter(i=>monthlyRecords(i).some(p=>p.currency===currency)).map(i=>i.itemId)).size} 条</span></label><div class="monthly-body"><div class="score-numbers"><label>最低<input type="number" data-month="${currency}" data-bound="min" min="${lo}" max="${hi}" step="0.01" value="${lo}" disabled></label><span>至</span><label>最高<input type="number" data-month="${currency}" data-bound="max" min="${lo}" max="${hi}" step="0.01" value="${hi}" disabled></label></div><div class="dual-range" style="--lo:0%;--hi:100%"><div class="range-track"></div><input type="range" data-month="${currency}" data-bound="min" min="${lo}" max="${hi}" step="0.01" value="${lo}" disabled aria-label="${currency}月均价格最低值"><input type="range" data-month="${currency}" data-bound="max" min="${lo}" max="${hi}" step="0.01" value="${hi}" disabled aria-label="${currency}月均价格最高值"></div></div></section>`;}).join('');}
function halfHourOptions(){return '<option value="">不限</option>'+Array.from({length:48},(_,i)=>{const t=String(Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00');return `<option value="${t}">${t}</option>`;}).join('');}
function setupWorkbench(spec,imageData){wb.spec=spec;if(state.items.some(i=>skillHistoricalFact(i,'ip_usage_location'))){WB_LABELS.usage_location='IP数据库使用地';WB_LABELS.registration_location='IP注册地（非机房）';}wb.imageData=imageData;const map=new Map(state.items.map(i=>[i.itemId,i]));for(const e of imageData.entries||[]){const i=map.get(e.itemId);if(i&&(!e.postId||String(e.postId)===String(i.postId)))i.imageEvidence=e;}
 for(const field of spec.fields)wb.coverage[field.key]=coverageFor(field.key);
 const slots={country_region:'country',city:'city',provider:'vendor',cpu_model:'cpuModel',disk_type:'diskType'};
 const panels=spec.groups.map((group,gi)=>{const fs=spec.fields.filter(f=>f.group===group.name),cards=[],pending=[];for(const f of fs){const key=f.key,count=wb.coverage[key];if(['test_time_bjt','geekbench_multi'].includes(key))continue;
 if(key==='test_date'){cards.push(controlCard('测试日期与北京时间',`<div class="range-fields"><label>起始日期<input type="date" id="dateStart"></label><label>结束日期<input type="date" id="dateEnd"></label><label data-spec-field="test_time_bjt">每天开始时间<select id="timeStart" aria-label="每天开始时间">${halfHourOptions()}</select></label><label>每天结束时间<select id="timeEnd" aria-label="每天结束时间">${halfHourOptions()}</select></label></div><p class="field-help">时间按 30 分钟选择；跨午夜范围可用。只匹配已确认时区的同一份报告，不以发帖时间替代。不同模块分别保留时间。</p>`,count,key,'wide-field'));continue;}
 if(key==='monthly_price'){cards.push(controlCard('月均价格 · 按币种独立区间',`<div id="monthly-ranges" class="monthly-ranges">${monthlyControls()}</div><p class="field-help">勾选后启用。明确月报价直接保留；已知年付÷12、季付÷3、两年÷24、三年÷36。月均价不证明实际可月付；周期未知不倒推账单，各币种不换汇。</p><div class="supplemental-controls"><div id="currency" class="multi-slot"></div><div id="priceKind" class="multi-slot"></div></div>`,count,key,'wide-field'));continue;}
 if(key==='billing_period'){cards.push(`<p class="display-only" data-spec-field="billing_period">付款周期随结果与价格原文展示，不作为筛选条件。</p>`);continue;}
 if(['vcpu','memory_capacity','disk_capacity'].includes(key)){const id={vcpu:'cpu',memory_capacity:'memory',disk_capacity:'disk'}[key];cards.push(controlCard(fieldLabel(key),`<p class="field-help">使用顶部常用条件。默认严格 &gt;，可切换 ≥。</p><button class="text-button" type="button" data-focus-input="${id}">定位到${escapeHTML(fieldLabel(key))}条件</button>`,count,key));continue;}
 if(key==='geekbench_single'){cards.push(controlCard('Geekbench 单核 / 多核',`<div id="benchmark" class="multi-slot"></div><div id="score-ranges"></div><p class="field-help" id="score-coverage"></p><p class="field-help" data-spec-field="geekbench_multi">按 GB5 / GB6 和单核 / 多核分成四个区间。仅筛主观测；下限可作最低分条件。</p>`,count,key,'wide-field'));continue;}
 if(key==='return_routes'||key==='outbound_routes'){if(count)cards.push(routeMatrix(key==='return_routes'?'return':'outbound'));else pending.push(f);continue;}
 if(!count){pending.push(f);continue;}
 if(slots[key])cards.push(legacySlot(slots[key],fieldLabel(key),count,key));else if(WB_MULTIS.has(key))cards.push(controlCard(fieldLabel(key),wbMulti(key),count,key));else cards.push(controlCard(fieldLabel(key),`<label class="value-threshold">大于<input type="number" min="0" step="any" data-wb-number="${key}" placeholder="不限" aria-label="${escapeHTML(fieldLabel(key))}阈值"><span>${escapeHTML(f.unit||'')}</span></label>${key.startsWith('disk_')?'<p class="field-help">按负载 / 队列 / 读写方向检索历史吞吐值；工具标签在详情保留，版本/文件大小不全，不作受控横向排名。</p>':''}${key.startsWith('hardware_')?'<p class="field-help">仅比较本次相同 HardwareQuality v2026-05-21 评分体系；不与GB/Sysbench相加。</p>':''}${key==='port_bandwidth'?'<p class="field-help">套餐标称端口，不等于实际测速。</p>':''}`,count,key));}
 if(group.name==='地理信息')cards.push(controlCard('资料类型',`<div id="itemType" class="multi-slot"></div>`,state.items.length,'support_item_type'));
 if(group.name==='网络信息')cards.push(controlCard('线路总览 · 保留原来源口径',`<div class="supplemental-controls"><div id="route" class="multi-slot"></div><div id="routeSource" class="multi-slot"></div></div><p class="field-help">总览标签可能只来自标题或作者宣称；需要方向和协议时，使用上方精确矩阵。</p>`,state.items.filter(i=>i.network.filterRouteTags.length).length,'support_route_tags','wide-field'));
 const usable=fs.filter(f=>wb.coverage[f.key]>0&&f.key!=='billing_period').length;
 return `<section class="group-panel" id="group-${gi}" data-group="${escapeHTML(group.name)}" ${group.name!==wb.activeGroup?'hidden':''}><div class="group-header"><h2>${escapeHTML(group.name)}</h2><span>${usable} / ${group.count} 项已有可筛数据</span></div><div class="field-grid">${cards.join('')}</div>${pendingFields(pending)}</section>`;});
 $('group-panels').innerHTML=panels.join('');$('group-nav').innerHTML=spec.groups.map((g,i)=>`<button type="button" data-group-tab="${i}" aria-current="${g.name===wb.activeGroup?'true':'false'}"><span>${escapeHTML(g.name.replace('信息',''))}</span><small>${spec.fields.filter(f=>f.group===g.name&&wb.coverage[f.key]>0).length}/${g.count}</small></button>`).join('');
}
function wbActiveCount(){return Object.values(wb.dynamic).filter(v=>Array.isArray(v)?v.length:v!=='').length+Object.values(wb.monthly).filter(r=>r.enabled).length+[wb.dateStart||wb.dateEnd,wb.timeStart||wb.timeEnd].filter(Boolean).length;}
function workbenchChips(){let html='';for(const[key,value]of Object.entries(wb.dynamic)){if(Array.isArray(value)?!value.length:value==='')continue;const label=key.startsWith('route:')?key.split(':').slice(1).map(v=>v==='return'?'回程':v==='outbound'?'去程':v).join(' · '):fieldLabel(key);html+=`<button class="chip" data-wb-clear="${escapeHTML(key)}">${escapeHTML(label)}：${escapeHTML(Array.isArray(value)?value.join('、'):'> '+value)} ×</button>`;}for(const[cur,r]of Object.entries(wb.monthly))if(r.enabled)html+=`<button class="chip" data-wb-clear="monthly:${cur}">${cur} 月均 ${r.min}–${r.max} ×</button>`;if(wb.dateStart||wb.dateEnd)html+=`<button class="chip" data-wb-clear="dates">日期 ${wb.dateStart||'不限'} 至 ${wb.dateEnd||'不限'} ×</button>`;if(wb.timeStart||wb.timeEnd)html+=`<button class="chip" data-wb-clear="times">北京时间 ${wb.timeStart||'不限'}–${wb.timeEnd||'不限'} ×</button>`;return html;}
function refreshWorkbenchBadges(){if(!wb.spec)return;const additional=workbenchChips();if(additional){$('active-filters').hidden=false;$('active-filters').innerHTML+=additional;}const f=currentFilters();const total=fields.filter(k=>filterActive(f,k)).length+wbActiveCount();$('active-group-count').textContent=total?`${total} 组条件已启用`:'全部条件不限';$('mobile-filters').textContent=$('filter-panel').hidden?'展开条件':'收起条件';$('mobile-filters').setAttribute('aria-expanded',String(!$('filter-panel').hidden));}
function resetWorkbench(){wb.dynamic={};wb.dateStart=wb.dateEnd=wb.timeStart=wb.timeEnd='';for(const id of['dateStart','dateEnd','timeStart','timeEnd'])if($(id))$(id).value='';for(const key of['cpu','memory','disk'])if($(key+'Op'))$(key+'Op').value='>';for(const r of Object.values(wb.monthly)){r.enabled=false;r.min=r.domainMin;r.max=r.domainMax;}for(const el of document.querySelectorAll('[data-wb-number]'))el.value='';for(const el of document.querySelectorAll('[data-wb-multi],[data-month-enable]')){el.checked=false;if(el.dataset.wbMulti){const summary=el.closest('details')?.querySelector('summary');if(summary)summary.innerHTML='不限 <span>可多选</span>';}}for(const el of document.querySelectorAll('[data-wb-search]'))el.value='';for(const el of document.querySelectorAll('[data-wb-option]'))el.hidden=false;syncMonthlyInputs();}
function syncMonthlyInputs(){for(const el of document.querySelectorAll('[data-month]')){const r=wb.monthly[el.dataset.month];el.value=r[el.dataset.bound];el.disabled=!r.enabled;const box=el.closest('.monthly-box');if(box){const track=box.querySelector('.dual-range'),span=r.domainMax-r.domainMin;track.style.setProperty('--lo',`${span?(r.min-r.domainMin)/span*100:0}%`);track.style.setProperty('--hi',`${span?(r.max-r.domainMin)/span*100:100}%`);}}}
function clearWorkbench(key){if(key.startsWith('monthly:')){const cur=key.slice(8);wb.monthly[cur].enabled=false;const check=document.querySelector(`[data-month-enable="${cur}"]`);if(check)check.checked=false;syncMonthlyInputs();}else if(key==='dates'||key==='times'){const ids=key==='dates'?['dateStart','dateEnd']:['timeStart','timeEnd'];for(const id of ids){wb[id]='';$(id).value='';}}else{delete wb.dynamic[key];for(const el of document.querySelectorAll('[data-wb-multi],[data-wb-number]'))if(el.dataset.wbMulti===key){el.checked=false;const summary=el.closest('details')?.querySelector('summary');if(summary)summary.innerHTML='不限 <span>可多选</span>';}else if(el.dataset.wbNumber===key)el.value='';}state.page=1;render();}
function compactRecords(entries){const rows=entries.map(item=>{const c=item.configuration,p=primaryPrice(item),monthly=p?monthlyValue(p):null,gb=benchmarks(item).filter(b=>b.tool==='Geekbench'&&b.isPrimary!==false).slice(0,2);const hasImage=!!item.imageEvidence,hasSkill=!!item.skillReview;return `<tr><td class="product-cell"><span class="table-vendor">${escapeHTML(item.vendor||'商家未知')}</span><button class="title-button" data-detail="item:${escapeHTML(item.itemId)}">${escapeHTML(item.product||item.label)}</button><span class="table-meta">#${item.postId} · ${escapeHTML(typeLabels[item.itemType])}</span></td><td><strong>${c.vcpu??'未知'}${c.vcpu!=null?' 核':''}</strong><span class="cell-secondary">${escapeHTML(capacityText(c.memoryValue,c.memoryUnit))} RAM</span><span class="cell-secondary">${escapeHTML(capacityText(c.diskValue,c.diskUnit))}</span>${skillCapacityNote(item)?`<span class="cell-secondary">${escapeHTML(skillCapacityNote(item))}</span>`:''}</td><td class="cpu-cell"><span>${escapeHTML(c.cpuModel||'型号未知')}</span>${gb.map(b=>`<small>GB${b.majorVersion} ${metricLabels[b.metric]||b.metric} <b>${b.score}</b></small>`).join('')}</td><td><span>${escapeHTML(getLocation(item)||'地区未知')}</span><div class="route-tags">${routes(item)}</div></td><td class="price-cell">${priceText(p)}${monthly!=null?`<span class="monthly-value">≈ ${p.currency} ${monthly.toFixed(2)} / 月</span>`:'<span class="cell-secondary">月均未确认</span>'}</td><td><span class="source-pill ${hasImage?'image-source':''}">${hasSkill?skillRecordLabel(item):hasImage?'有图片事实':'正文 / 报告'}</span><span class="cell-secondary">${dateLabel(item)}</span><button class="detail-link" data-detail="item:${escapeHTML(item.itemId)}">事实与来源</button></td></tr>`;}).join('');return `<div class="desktop-results"><table class="result-table"><thead><tr><th>产品 / 原帖</th><th>规格</th><th>CPU / 主观测</th><th>地区 / 线路</th><th>历史价格 / 周期</th><th>证据 / 时间</th></tr></thead><tbody>${rows}</tbody></table></div><div class="mobile-results">${entries.map(itemCard).join('')}</div>`;}
function evidenceRef(evidence){const images=evidence?.evidenceImages||[];return images.map(im=>`${im.name}${im.sha256?' · SHA256 '+im.sha256.slice(0,12):''}`).join('；');}
function imageEvidenceDetails(item){const e=item.imageEvidence;if(!e)return '';const fs=e.fieldObservations||[],routes=e.routeObservations||[],lat=e.latencyObservations||[];const fieldsHtml=fs.map(f=>`<tr><td>${escapeHTML(fieldLabel(f.fieldKey))}</td><td>${escapeHTML(Array.isArray(f.value)?f.value.join('、'):f.value??'未知')} ${escapeHTML(f.unit||'')}<small>${f.factKind==='advertised_plan'?'套餐宣称':'报告所见'} · ${f.isPrimary?'主观测':'历史对照'}</small></td><td>${escapeHTML(f.note||f.comparisonScope||'既有图片核读记录')}<small>${escapeHTML(evidenceRef(f.evidence))}</small></td></tr>`).join('');const routeHtml=routes.map(r=>`<tr><td>${escapeHTML(r.family)} · ${r.direction==='return'?'回程':'去程'}<br>${escapeHTML(r.operator||r.carrier||'运营商关联未知')}</td><td>${escapeHTML((r.reportedLabels||[]).join('、'))}<small>${r.filterEligible&&r.isPrimary!==false?'可筛历史标签':'仅供查看，不参与筛选'}</small></td><td>${escapeHTML(r.matchSemantics||r.note||'报告部分目标的标签，不是全网或长期保证')}<small>${escapeHTML(evidenceRef(r.evidence))}</small></td></tr>`).join('');const latencyHtml=lat.slice(0,12).map(r=>`<div class="report"><strong>${escapeHTML(r.family)} · ${escapeHTML(r.operator||r.carrier||'运营商未知')}</strong><p>方法：${escapeHTML(r.metric==='tcpquality_report_latency'?'TCPQuality 回程延迟（非 ICMP Ping）':r.metric||'报告延迟')}；统计：${escapeHTML(({range:'测点范围',mean_complete_matrix_valid_rows:'完整矩阵有效测点的算术均值'}[r.statistic]||r.statistic||'未知'))}</p><p>值：${escapeHTML(r.value!=null?typeof r.value==='object'?JSON.stringify(r.value):r.value:r.min!=null?`${r.min}–${r.max}`:r.range?JSON.stringify(r.range):'详见记录')} ${escapeHTML(r.unit||'')}</p>${r.validCount!=null||r.validSamples!=null||r.sampleCount!=null?`<p>有效测点：${r.validCount??r.validSamples??r.sampleCount} / ${r.targetCount??'未知'}；失败：${r.failedSamples??r.failedCount??'未知'}</p>`:''}${notes(r.scope)}${notes(r.note)}<p class="detail-note">不用于通用平均 Ping 筛选。</p></div>`).join('');return `<section class="detail-section image-evidence-section"><h3>来自图片的结构化事实</h3><p class="detail-note">复用既有图片核读记录，本次未重新查看像素。原图不公开、不加载；保留图序号、内容哈希和原帖链接以便核对。</p>${fieldsHtml?`<table class="route-table"><thead><tr><th>字段</th><th>值 / 口径</th><th>依据与限制</th></tr></thead><tbody>${fieldsHtml}</tbody></table>`:''}${routeHtml?`<h4>协议 × 方向 × 运营商</h4><table class="route-table"><thead><tr><th>线路范围</th><th>标签</th><th>证据</th></tr></thead><tbody>${routeHtml}</tbody></table>`:''}${latencyHtml?`<details><summary>延迟与 RTT 口径（不当作平均 Ping）</summary><div class="report-list">${latencyHtml}</div></details>`:''}${e.networkSamples?.length?notes(`另保留 ${e.networkSamples.length} 条单线程测速样本，属于明确地点的 RTT / 吞吐观测，未合成为全国平均 Ping。`):''}${e.monitorSnapshots?.length?notes('本对象有监控面板快照；探针与观测时间口径不完整，只作历史参考，不用作筛选。'):''}</section>`;}
function evidenceOverview(){const counted=wb.spec.fields.filter(f=>wb.coverage[f.key]>0&&f.key!=='billing_period').length;const c=wb.imageData.counts||{};const imageKeys=Object.entries(wb.imageData.fieldCoverage||{}).filter(([,v])=>v.filterEligibleItems>0);return `<div class="eyebrow">来源可追溯，口径不混用</div><h2 id="evidence-title">图片信息已经进入筛选。</h2><p class="detail-summary">${c.entriesWithNewProjection||41} 条对象保留既有结构化图片事实。${state.skillRefresh?.currentBatch?`${state.skillRefresh.pipelineIntegration?'基础目录上一批':'本批'}另实际读取 ${state.skillRefresh.currentBatch.imagesReviewed} 个图片文件（含报告图及标志、表情等素材），逐条保留来源；文件数不等于测评图或机器数。`:''}当前 ${counted} / 53 项规范字段有可筛数据；付款周期只展示，尚无可靠数据的项单列说明。</p><div class="evidence-stats"><div><strong>${c.reviewedImages||172}</strong><span>既有图像核读记录</span></div><div><strong>${state.items.filter(i=>(i.imageEvidence?.routeObservations||[]).some(r=>r.filterEligible&&r.isPrimary!==false)).length}</strong><span>条对象可筛精确回程</span></div><div><strong>0</strong><span>通用平均 Ping 筛选</span></div></div><section class="detail-section"><h3>现在可用</h3><p>ASN、组织、部分系统信息、套餐端口 / IP 数量、内存机制迹象和分负载 硬盘吞吐值。线路按 IPv4 / IPv6、方向和运营商精确匹配；商品宣称与实测报告保留区别。</p><div class="coverage-list">${imageKeys.map(([k,v])=>`<span>${escapeHTML(fieldLabel(k))}<strong>${v.filterEligibleItems} 条</strong></span>`).join('')}</div></section><section class="detail-section"><h3>不会自动变成筛选结论的内容</h3><ul class="warning-list"><li>TCPQuality 矩阵范围、测点均值和单线程 RTT 不冒充 ICMP 或通用平均 Ping。</li><li>IP 地理位置不当作机房确认；流媒体“原生解锁”不当作原生 IP 判定。</li><li>Sysbench 版本、单位或参数不完整时，只展示读数，不放进混合区间。</li><li>旧阶段、失败矩阵、无法关联运营商的标签和探针未知的监控快照不进入默认筛选。</li></ul></section><section class="detail-section"><h3>一条图片事实如何可筛</h3><ol class="method-steps"><li>与具体帖子、测试对象和报告阶段绑定</li><li>读取字段并保留单位、工具 / 版本、协议及测量条件</li><li>核对图序号和内容哈希，标注未知、冲突与来源类型</li><li>只开放满足当前字段口径的筛选，详情仍可追溯证据</li></ol><p class="detail-note">上方既有图片统计来自保存的核读结果；本批新增来源另经实际素材阅读与61字段复核，阅读范围和缺失情况在对象详情中单列。</p></section>`;}
function completeWorkbench(){if(window.matchMedia&&window.matchMedia('(max-width:800px)').matches)$('filter-panel').hidden=true;document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.groupTab!=null){const index=Number(b.dataset.groupTab);wb.activeGroup=wb.spec.groups[index].name;for(const p of document.querySelectorAll('.group-panel'))p.hidden=p.id!==`group-${index}`;for(const t of document.querySelectorAll('[data-group-tab]'))t.setAttribute('aria-current',String(t===b));}if(b.dataset.focusInput)$(b.dataset.focusInput).focus();if(b.dataset.wbClear)clearWorkbench(b.dataset.wbClear);});document.addEventListener('change',e=>{const t=e.target;if(t.dataset.wbMulti){const key=t.dataset.wbMulti;wb.dynamic[key]=[...document.querySelectorAll('[data-wb-multi]:checked')].filter(el=>el.dataset.wbMulti===key).map(el=>el.value);const summary=t.closest('details')?.querySelector('summary');if(summary)summary.innerHTML=wb.dynamic[key].length?`${wb.dynamic[key].length} 项已选 <span>可多选</span>`:'不限 <span>可多选</span>';state.page=1;render();}if(t.dataset.monthEnable){wb.monthly[t.dataset.monthEnable].enabled=t.checked;syncMonthlyInputs();state.page=1;render();}});document.addEventListener('input',e=>{const t=e.target;if(t.dataset.wbNumber){wb.dynamic[t.dataset.wbNumber]=t.value;state.page=1;render();}if(t.dataset.wbSearch){for(const l of t.closest('details').querySelectorAll('[data-wb-option]'))l.hidden=!l.dataset.wbOption.includes(t.value.toLowerCase());}if(t.dataset.month){const r=wb.monthly[t.dataset.month],n=Number(t.value);if(Number.isFinite(n)){const value=Math.max(r.domainMin,Math.min(r.domainMax,n));if(t.dataset.bound==='min')r.min=Math.min(value,r.max);else r.max=Math.max(value,r.min);syncMonthlyInputs();state.page=1;render();}}});for(const id of['dateStart','dateEnd','timeStart','timeEnd'])$(id).addEventListener('input',()=>{wb[id]=$(id).value;state.page=1;render();});for(const id of['cpuOp','memoryOp','diskOp'])$(id).addEventListener('change',refresh);$('mobile-filters').onclick=()=>{$('filter-panel').hidden=!$('filter-panel').hidden;refreshWorkbenchBadges();};$('evidence-open').onclick=()=>{$('evidence-content').innerHTML=evidenceOverview();$('evidence-dialog').showModal();};$('evidence-close').onclick=()=>$('evidence-dialog').close();$('spec-coverage').textContent=`9 组 · 53 项 · ${wb.spec.fields.filter(f=>wb.coverage[f.key]>0&&f.key!=='billing_period').length} 项可筛`;}

function displayedPrice(item){const enabled=Object.entries(wb.monthly).filter(([,r])=>r.enabled);if(enabled.length){const f=currentFilters();const found=monthlyRecords(item).find(p=>multiMatch(p.currency,f.currency)&&multiMatch(p.priceKind,f.priceKind)&&enabled.some(([cur,r])=>p.currency===cur&&p.monthly>=r.min-1e-9&&p.monthly<=r.max+1e-9));if(found)return found;}return basePrimaryPrice(item);}
